def transform(grid):
    grid = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells)
            c0 = min(x for y, x in cells)
            shape = frozenset((y-r0, x-c0) for y, x in cells)
            components.append((color, cells, shape))
    templates = {}
    for color, cells, shape in components:
        if color != 1:
            templates.setdefault(shape, color)
    for color, cells, shape in components:
        if color == 1 and shape in templates:
            for r, c in cells:
                grid[r][c] = templates[shape]
    return grid
